Item.method_code:
/*
    標準のInitの改造
        対象ユーザーなら親アイテムの状態に関係なく追加できるようにする
*/

// // Innovatorオブジェクト生成
var iomInv = aras.IomInnovator;

// 親Item情報取得
var parentItem = iomInv.newItem(itemTypeName,"get");
parentItem.setID(itemID);
parentItem.setAttribute("select", "managed_by_id,state");
parentItem = parentItem.apply();

// アイテムが取得出来ない場合(新規作成時)は非表示
if(parentItem.getItemCount()<1) return {hidden:true};

// ステートが作業中または改訂中の時以外は非表示
var state = parentItem.getProperty("state", "");
if(state!="InProgress" && state!="InRevision") return {hidden:true};

// 以降標準メソッドcui_ivrcb_create_item_init
const relOption = aras.getItemProperty(options.relationshipTypeNode, 'related_option');
const relId = aras.getItemProperty(options.relationshipTypeNode, 'related_id');
let tooltip = '';
if (options.relatedItemTypeId) {
  const relatedItemTypeLabel = aras.getItemProperty(options.relatedItemTypeNode, 'label');
  tooltip = target.tooltip_template.replace('{0}', relatedItemTypeLabel || options.relatedTypeName);
}
return {
  disabled: !(window.computeCorrectControlState && window.computeCorrectControlState('new')),
  hidden: relId === '' || !(relOption === '1' || relOption === '2'), // 1 or 2 are related options to allow create item
  tooltip_template: tooltip
};
